"""MOTIF QC-003 — an aperture generated by a failing local representation.

Research-only, classical, deterministic and synthetic. The learner receives
unlabeled graph before/after pairs: no action cue and NO supplied anchors.
It induces edge-local rewrite templates, compares candidate relational
observations, and optionally constructs a fixed-point reachability question
when every local descriptor fails to separate two effect families.

This is a bounded search over *known mathematical constructors*, not
unrestricted new mathematics, quantum computing, nor a production agent.
"""
from __future__ import annotations

from collections import Counter, defaultdict, deque
from dataclasses import dataclass
from hashlib import sha256
from itertools import combinations, permutations
from pathlib import Path
import json
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "quantumcode002"))
from structural import Graph, edge

PROVENANCE = "SYNTHETIC_QC003"
STATUS = "LOCAL_PREVIEW_ONLY"
LOCAL = ("shared_neighbor", "end_degrees", "ego2_size", "ego2_edges",
         "graph_order_even", "graph_edges_even", "graph_connected")
GENERATED = "CUT_EDGE__NEIGHBOR_CLOSURE__CAN_REACH_OTHER_END"
SPLITS = ("TRAIN", "VALIDATE", "TEST")


def digest(x) -> str:
    return sha256(json.dumps(x, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


@dataclass(frozen=True, order=True)
class Template:
    """Canonical graph-delta schema; roles O0/O1 inferred, N0.. newly made."""
    old_roles: int
    new_roles: int
    remove_edges: tuple[tuple[str, str], ...]
    add_edges: tuple[tuple[str, str], ...]
    anchor_edge_required: bool

    def seal(self) -> str:
        return digest((self.old_roles, self.new_roles, self.remove_edges,
                       self.add_edges, self.anchor_edge_required))[:18]


@dataclass(frozen=True)
class Episode:
    evidence_id: str
    split: str
    before: Graph
    after: Graph
    provenance: str = PROVENANCE

    def check(self, split: str):
        if (self.provenance != PROVENANCE or self.split != split or
                not self.evidence_id):
            raise ValueError("Invalid or non-synthetic episode")


def check_batch(records: tuple[Episode, ...], split: str):
    if len({x.evidence_id for x in records}) != len(records):
        raise ValueError("Repeated receipt")
    for x in records:
        x.check(split)


def infer_delta(row: Episode) -> tuple[tuple[str, str], Template]:
    """Infer changed roles from graph delta, not from node names or action cues."""
    row.check(row.split)
    before, after = row.before, row.after
    new = after.vertices - before.vertices
    if not before.vertices.issubset(after.vertices) or not 1 <= len(new) <= 3:
        raise ValueError("Unsupported vertex deletion/addition")
    removed = before.edges - after.edges
    added = after.edges - before.edges
    touched = {v for a, b in added | removed for v in (a, b)
               if v in before.vertices}
    if len(touched) != 2:
        raise ValueError("Cannot infer unique two-node boundary from changes")
    anchors = tuple(sorted(touched))
    if edge(*anchors) not in before.edges:
        raise ValueError("This graph aperture requires an existing boundary edge")
    if not removed.issubset({edge(*anchors)}):
        raise ValueError("Nonlocal old-edge deletion")
    if not added or any(not set(e).issubset(touched | new) for e in added):
        raise ValueError("Nonlocal edge addition")
    # Every fresh vertex must participate in the modification.
    if not new.issubset({v for e in added for v in e}):
        raise ValueError("Dangling fresh vertex")
    # Enumerate all role assignments: the representation is alpha-invariant.
    variants = []
    for old_order in permutations(anchors):
        for new_order in permutations(sorted(new)):
            mapper = {n: f"O{i}" for i, n in enumerate(old_order)}
            mapper.update({n: f"N{i}" for i, n in enumerate(new_order)})
            transform = lambda e: tuple(sorted(mapper[v] for v in e))
            variants.append(Template(
                len(anchors), len(new),
                tuple(sorted(transform(e) for e in removed)),
                tuple(sorted(transform(e) for e in added)),
                True))
    chosen = min(variants)
    return anchors, chosen


def local_feature(graph: Graph, anchors: tuple[str, str], name: str):
    a, b = anchors
    if edge(a, b) not in graph.edges:
        raise ValueError("Feature query needs an existing edge")
    neighbors = {n: {v for e in graph.edges for v in e if n in e and v != n}
                 for n in graph.vertices}
    if name == "shared_neighbor":
        return len(neighbors[a] & neighbors[b])
    if name == "end_degrees":
        return tuple(sorted((len(neighbors[a]), len(neighbors[b]))))
    if name in ("ego2_size", "ego2_edges"):
        visited = {a, b}
        frontier = {a, b}
        for _ in range(2):
            frontier = {v for n in frontier for v in neighbors[n]} - visited
            visited.update(frontier)
        return (len(visited) if name == "ego2_size"
                else sum(set(e).issubset(visited) for e in graph.edges))
    if name == "graph_order_even":
        return len(graph.vertices) % 2 == 0
    if name == "graph_edges_even":
        return len(graph.edges) % 2 == 0
    if name == "graph_connected":
        return len(closure(graph, a, None)) == len(graph.vertices)
    raise ValueError("Unknown local candidate")


def closure(graph: Graph, start: str, excluded_edge: tuple[str, str] | None):
    """Finite fixed-point closure generated from NEIGHBOR + UNION constructors.

    This is a conventional reachability computation. The feature selector
    can introduce it only after no predeclared local question discriminates.
    """
    reached = frozenset((start,))
    while True:
        expanded = reached | frozenset(
            v for a, b in graph.edges if (a, b) != excluded_edge
            for v in ((b,) if a in reached else ()) +
                     ((a,) if b in reached else ()))
        if expanded == reached:
            return reached
        reached = expanded


def feature(graph: Graph, anchors: tuple[str, str], name: str):
    if name in LOCAL:
        return local_feature(graph, anchors, name)
    if name == GENERATED:
        a, b = anchors
        return b in closure(graph, a, edge(a, b))
    raise ValueError("Unrecognized feature program")


@dataclass(frozen=True)
class Proposal:
    train_digest: str
    effects: tuple[Template, ...]
    feature_program: str
    truth_table: tuple[tuple[str, str], ...]
    locality_failed: bool
    status: str = "PROPOSAL_ONLY"

    def rule_for(self, value) -> str | None:
        return dict(self.truth_table).get(str(value))


@dataclass(frozen=True)
class Reviewed:
    proposal: Proposal
    valid_digest: str
    validated: int
    status: str = STATUS

    def pin(self):
        return digest((self.proposal.train_digest, self.proposal.feature_program,
                       self.proposal.truth_table, self.valid_digest))


def labelled(records: tuple[Episode, ...]):
    data = []
    for row in records:
        anchors, effect = infer_delta(row)
        data.append((row, anchors, effect))
    return tuple(data)


def training_manifest(records: tuple[Episode, ...]):
    return digest(sorted((r.evidence_id, r.before.receipt(), r.after.receipt())
                         for r in records))


def candidate_feature(data, program: str):
    """Return a two-class deterministic, invertible binary feature table."""
    by_feature = defaultdict(set)
    by_effect = defaultdict(set)
    for row, anchors, effect in data:
        value = feature(row.before, anchors, program)
        by_feature[str(value)].add(effect.seal())
        by_effect[effect.seal()].add(str(value))
    if (len(by_effect) != 2 or len(by_feature) != 2 or
            any(len(x) != 1 for x in by_feature.values()) or
            any(len(x) != 1 for x in by_effect.values())):
        return None
    return tuple(sorted((key, next(iter(values)))
                        for key, values in by_feature.items()))


def discover(train: tuple[Episode, ...], minimum: int = 3) -> Proposal | None:
    """Discover effect families and a distinguishing relational *question*."""
    check_batch(train, "TRAIN")
    if minimum < 2:
        raise ValueError("Require independent synthetic training examples")
    data = labelled(train)
    effects = tuple(sorted({d[2] for d in data}))
    if len(effects) != 2:
        return None
    for effect in effects:
        if sum(row_effect == effect for _, _, row_effect in data) < minimum:
            return None
    local_tables = [(f, candidate_feature(data, f)) for f in LOCAL]
    available = next(((f, t) for f, t in local_tables if t is not None), None)
    if available is None:
        # Bounded aperture lift: compose CUT_EDGE, NEIGHBOR and FIXPOINT.
        # This is a *known* graph algorithm, generated as a new query in the
        # tested representation, not an invented mathematical fact.
        selected, table = GENERATED, candidate_feature(data, GENERATED)
        failed = True
    else:
        selected, table = available
        failed = False
    if table is None:
        return None
    return Proposal(training_manifest(train), effects, selected, table, failed)


def review(candidate: Proposal | None,
           train: tuple[Episode, ...],
           validation: tuple[Episode, ...],
           minimum: int = 2) -> Reviewed | None:
    check_batch(train, "TRAIN")
    check_batch(validation, "VALIDATE")
    if {x.evidence_id for x in train} & {x.evidence_id for x in validation}:
        raise ValueError("Cross-split receipt reuse")
    reconstructed = discover(train)
    if candidate is None or candidate != reconstructed or candidate.status != "PROPOSAL_ONLY":
        raise ValueError("Unreconstructible feature discovery")
    data = labelled(validation)
    observed = Counter()
    for row, anchors, effect in data:
        got = candidate.rule_for(feature(row.before, anchors, candidate.feature_program))
        if got is None or got != effect.seal():
            return None
        observed[effect.seal()] += 1
    if set(observed) != {r.seal() for r in candidate.effects}:
        return None
    if min(observed.values()) < minimum:
        return None
    return Reviewed(candidate, training_manifest(validation), len(validation))


def make_fresh(graph: Graph, count: int):
    names = []
    i = 0
    while len(names) < count:
        n = f"qc003_new_{i}"
        if n not in graph.vertices:
            names.append(n)
        i += 1
    return tuple(names)


def apply_template(graph: Graph, anchors: tuple[str, str],
                   template: Template) -> Graph | None:
    if (template.old_roles != 2 or not 1 <= template.new_roles <= 3
            or not set(anchors).issubset(graph.vertices) or
            len(set(anchors)) != 2 or
            (edge(*anchors) in graph.edges) != template.anchor_edge_required):
        return None
    fresh = make_fresh(graph, template.new_roles)
    # Prefer canonical old-role order and test both assignments.
    # Identical anchor automorphisms produce equivalent outputs.
    mapping = {"O0": min(anchors), "O1": max(anchors)}
    mapping.update({f"N{i}": n for i, n in enumerate(fresh)})
    allowed = set(mapping)
    if any(set(e) - allowed for e in template.remove_edges+template.add_edges):
        return None
    remove = {edge(mapping[a], mapping[b]) for a, b in template.remove_edges}
    additions = {edge(mapping[a], mapping[b]) for a, b in template.add_edges}
    if not remove.issubset(graph.edges):
        return None
    result = Graph.of(graph.vertices | set(fresh), (graph.edges - remove) | additions)
    return result


@dataclass(frozen=True)
class Step:
    anchor: tuple[str, str]
    effect: str
    relation: str
    source_pin: str
    before: str
    after: str


@dataclass(frozen=True)
class World:
    graph: Graph
    history: tuple[Step, ...] = ()


def preview(world: World, anchors: tuple[str, str], rules: Reviewed | None):
    if rules is None:
        return None
    if rules.status != STATUS or rules.proposal.status != "PROPOSAL_ONLY":
        raise ValueError("Unauthorized context or feature program")
    anchors = tuple(sorted(anchors))
    if len(anchors) != 2 or edge(*anchors) not in world.graph.edges:
        return None
    relation = feature(world.graph, anchors, rules.proposal.feature_program)
    effect_key = rules.proposal.rule_for(relation)
    template = next((t for t in rules.proposal.effects
                     if t.seal() == effect_key), None)
    if template is None:
        return None
    following = apply_template(world.graph, anchors, template)
    if following is None:
        return None
    step = Step(anchors, template.seal(), str(relation), rules.pin(),
                world.graph.receipt(), following.receipt())
    return World(following, world.history + (step,))


def enumerate_futures(world: World, rules: Reviewed | None):
    """No cue/anchor at inference: enumerate ALL candidates, never guess target."""
    result = []
    for anchors in sorted(world.graph.edges):
        future = preview(world, anchors, rules)
        if future is not None:
            result.append((anchors, future))
    return tuple(result)


def equivalent_new(before: Graph, expected: Graph, actual: Graph) -> bool:
    """Alpha-renaming equality keeping every existing old vertex fixed."""
    old = before.vertices
    enew, anew = expected.vertices-old, actual.vertices-old
    if (len(enew) != len(anew) or len(enew) > 3 or
            not old.issubset(expected.vertices) or
            not old.issubset(actual.vertices)):
        return False
    for permutation in permutations(sorted(anew)):
        remap = dict(zip(sorted(enew), permutation))
        normalized = {edge(remap.get(a, a), remap.get(b, b))
                      for a, b in expected.edges}
        if normalized == actual.edges:
            return True
    return False


# Independent evaluator: union-find instead of the learner's fixed-point
# neighbor closure. This is a *strong classical control*, not a physics oracle.
def independent_bridge(graph: Graph, ab: tuple[str, str]) -> bool:
    root = {n: n for n in graph.vertices}

    def find(n):
        while root[n] != n:
            n = root[n]
        return n

    def union(a, b):
        ra, rb = find(a), find(b)
        root[ra] = rb

    for a, b in graph.edges:
        if (a, b) != ab:
            union(a, b)
    return find(ab[0]) != find(ab[1])


def oracle_after(graph: Graph, ab: tuple[str, str],
                 additions_prefix: str = "oracle") -> Graph:
    """EVALUATOR ONLY. The learner never imports this into its selection."""
    if ab not in graph.edges:
        raise ValueError("Must modify existing edge")
    a, b = ab
    n0, n1 = f"{additions_prefix}_u", f"{additions_prefix}_v"
    if n0 in graph.vertices or n1 in graph.vertices:
        raise ValueError("Oracle node collision")
    add = {edge(a, n0), edge(n0, n1), edge(n1, b)}
    # Bridge -> retain edge and brace; cyclic edge -> subdivide.
    remove = set() if independent_bridge(graph, ab) else {ab}
    return Graph.of(graph.vertices | {n0, n1}, (graph.edges-remove) | add)


def sample_graph(prefix: str, cycle_n: int, tail_n: int, *,
                 chord: bool = False, second_tail: bool = False):
    """A long cycle and a long tail; two candidate edges have equal local views."""
    if min(cycle_n, tail_n) < 12:
        raise ValueError("Keep radius-two neighborhoods identical")
    cycle = [f"{prefix}_c{i}" for i in range(cycle_n)]
    tail = [f"{prefix}_t{i}" for i in range(tail_n)]
    edges = [edge(cycle[i], cycle[(i+1) % cycle_n]) for i in range(cycle_n)]
    edges += [edge(cycle[0], tail[0])]
    edges += [edge(tail[i], tail[i+1]) for i in range(tail_n-1)]
    vertices = set(cycle + tail)
    if chord:
        edges.append(edge(cycle[1], cycle[6]))
    if second_tail:
        extra = [f"{prefix}_q{i}" for i in range(4)]
        vertices.update(extra)
        edges += [edge(cycle[0], extra[0])]
        edges += [edge(extra[i], extra[i+1]) for i in range(3)]
    graph = Graph.of(vertices, edges)
    ec = edge(cycle[cycle_n//2], cycle[cycle_n//2+1])
    et = edge(tail[tail_n//2], tail[tail_n//2+1])
    return graph, (ec, et)


def fixture():
    parts = {}
    specs = {
        "TRAIN": [(12, 12, False, False), (14, 14, False, False),
                  (16, 16, False, False)],
        "VALIDATE": [(18, 18, False, False), (20, 20, False, False)],
        "TEST": [(22, 22, False, False), (24, 24, True, False),
                 (26, 26, False, True), (28, 28, True, True)],
    }
    for split, configs in specs.items():
        episodes = []
        for i, (m, n, chord, second_tail) in enumerate(configs):
            graph, targets = sample_graph(f"{split}-{i}", m, n,
                                          chord=chord, second_tail=second_tail)
            for position, ab in enumerate(targets):
                # For each source graph both outcomes exist, and no action
                # ID or target anchor is passed as input to the learner.
                after = oracle_after(graph, ab, f"{split}-{i}-{position}")
                episodes.append(Episode(f"{split}/{i}/{position}", split, graph, after))
        parts[split] = tuple(episodes)
    return parts["TRAIN"], parts["VALIDATE"], parts["TEST"]


def evaluate_on_test(rules: Reviewed, test: tuple[Episode, ...]):
    check_batch(test, "TEST")
    covered = correct = 0
    for row in test:
        anchors, _ = infer_delta(row)  # EVALUATOR uses outputs to match a target
        choices = dict(enumerate_futures(World(row.before), rules))
        if anchors not in choices:
            continue
        covered += 1
        correct += int(equivalent_new(row.before, row.after, choices[anchors].graph))
    return {"total": len(test), "covered": covered, "correct": correct,
            "wrong": covered-correct, "held": len(test)-covered}


def whole_graph_control(rules: Reviewed, graph: Graph):
    """Return precision and coverage on ALL eligible edges, not just target edges."""
    found = dict(enumerate_futures(World(graph), rules))
    actual = {ab: oracle_after(graph, ab, "blind_truth") for ab in graph.edges}
    common = set(found) & set(actual)
    correct = sum(equivalent_new(graph, actual[ab], found[ab].graph) for ab in common)
    return {"oracle_edges": len(actual), "predicted_edges": len(found),
            "correct": correct, "false_predictions": len(found)-correct,
            "missed": len(actual)-len(common)}


@dataclass(frozen=True)
class Macro:
    initial: str
    steps: tuple[Step, ...]
    expected_final: str
    status: str = STATUS


def compile_macro(beginning: World, end: World, rules: Reviewed) -> Macro:
    if beginning.history or not end.history:
        raise ValueError("Need a fresh initial state and actual change history")
    rebuilt = beginning
    for transition in end.history:
        rebuilt = preview(rebuilt, transition.anchor, rules)
        if rebuilt is None or rebuilt.history[-1] != transition:
            raise ValueError("Cannot compile unverified graph history")
    if rebuilt != end:
        raise ValueError("Observed outcome is not a verified replay")
    return Macro(beginning.graph.receipt(), end.history, end.graph.receipt())


def replay_macro(start: World, macro: Macro, rules: Reviewed | None):
    if (rules is None or macro.status != STATUS or start.history
            or start.graph.receipt() != macro.initial):
        return None
    current = start
    for step in macro.steps:
        current = preview(current, step.anchor, rules)
        if current is None or current.history[-1] != step:
            return None
    if current.graph.receipt() != macro.expected_final:
        return None
    return current


def run():
    train, valid, test = fixture()
    candidate = discover(train)
    certified = review(candidate, train, valid)
    if certified is None:
        raise AssertionError("The candidate feature failed validation")
    baseline_success = [x for x in LOCAL if candidate_feature(labelled(train), x)]
    sample, (_, bridge_target) = sample_graph("demo", 20, 20)
    start = World(sample)
    first = preview(start, bridge_target, certified)
    second = preview(first, bridge_target, certified)
    card = compile_macro(start, second, certified)
    macro_replay = replay_macro(start, card, certified)
    cases = []
    for i in (0, 1, 2, 3):
        cases.append(whole_graph_control(certified, test[2*i].before))
    return {
        "experiment": "QC-003",
        "status": "SYNTHETIC_REVIEW_ONLY",
        "train": len(train), "validation": len(valid), "test": len(test),
        "observed_edit_schemas": len(candidate.effects),
        "local_separating_features": baseline_success,
        "local_aperture_failed": candidate.locality_failed,
        "selected_program": candidate.feature_program,
        "relation_inferred_from": "CUT_EDGE + NEIGHBOR + FIXPOINT + MEMBERSHIP",
        "validation_count": certified.validated,
        "heldout_prediction": evaluate_on_test(certified, test),
        "all_edge_prediction": cases,
        "classical_union_find_oracle_all_edges_tied": all(
            r["false_predictions"] == 0 and r["missed"] == 0 for r in cases),
        "bridge_first": independent_bridge(start.graph, bridge_target),
        "bridge_after_first": independent_bridge(first.graph, bridge_target),
        "bridge_after_second": independent_bridge(second.graph, bridge_target),
        "two_phase_source_pinned_replay": macro_replay == second,
        "reentry_effects": [s.effect for s in second.history],
        "outside_actions": 0,
    }


if __name__ == "__main__":
    print(json.dumps(run(), sort_keys=True, indent=2))
